cd /home/cx/noodlespace/agentic-3js-builder/scratch/replay-app/treasureHoard && mkdir -p scratch/treasureHoard && cat > scratch/treasureHoard/run.ts <<'EOF'
import * as THREE from "three";
import build from "../../samples/treasureHoard";
const t0 = Date.now();
const root = build();
let parts = 0, tris = 0;
root.traverse((o) => { if ((o as THREE.Mesh).isMesh) { parts++; const g = (o as THREE.Mesh).geometry; tris += g.index ? g.index.count / 3 : g.attributes.position.count / 3; } });
const box = new THREE.Box3().setFromObject(root, true);
console.log("parts", parts, "tris", tris, "box", box.min.toArray().map(v=>v.toFixed(3)), box.max.toArray().map(v=>v.toFixed(3)), Date.now()-t0, "ms");
EOF
npx tsx scratch/treasureHoard/run.ts 2>&1 | tail -20
